export const CURATED_NIKE_BLOCK_LOCKUP_DESIGN_INTENT =
  "Curated Nike block lockup Manhattan v1: large block GPS-art lockup with a broad stair-stepped swoosh above JUST DO IT lettering. Features: swoosh, broad heel, rising tail, letters, wordmark, JUST DO IT, baseline, readable block logo.";

export function curatedNikeBlockLockupRouteKm(): number {
  let meters = 0;
  const coords = CURATED_NIKE_BLOCK_LOCKUP_MANHATTAN_COORDS;
  for (let i = 1; i < coords.length; i++) {
    meters += haversineMeters(coords[i - 1]!, coords[i]!);
  }
  return meters / 1000;
}

export function curatedNikeBlockLockupMapNativeCandidate(): MapNativeCandidate {
  const anchors = CURATED_NIKE_BLOCK_LOCKUP_MANHATTAN_COORDS;
  let minLat = Infinity;
  let maxLat = -Infinity;
  let minLng = Infinity;
  let maxLng = -Infinity;
  for (const [lat, lng] of anchors) {
    minLat = Math.min(minLat, lat);
    maxLat = Math.max(maxLat, lat);
    minLng = Math.min(minLng, lng);
    maxLng = Math.max(maxLng, lng);
  }
  return {
    placement: {
      center: [(minLat + maxLat) / 2, (minLng + maxLng) / 2],
      rotationDeg: 29,
      scale: 1,
    },
    anchors,
    km: curatedNikeBlockLockupRouteKm(),
    designIntent: CURATED_NIKE_BLOCK_LOCKUP_DESIGN_INTENT,
    kind: "street-wordmark",
    routeMode: "direct-grid",
  };
}

export function curatedNikeBlockLockupRouteLine(): RouteLineString {
  const coords = CURATED_NIKE_BLOCK_LOCKUP_MANHATTAN_COORDS;
  return {
    coordinates: coords,
    distanceMeters: curatedNikeBlockLockupRouteKm() * 1000,
    blockWaypoints: coords,
  };
}
